/* From Uiverse.io by mi-series - Tags: simple, material design, 3d, purple, minimalist, button, hover effect, hover button */
.__UIV_SCOPE__ .container {
  border: none;
}

.__UIV_SCOPE__ .container .card {
  background-color: white;
  border-radius: 10px;
  border: 1px solid black;
  position: relative;
  z-index: 0;
  transition: all 300ms ease-out;
  transform-origin: center center;
  width: 150px;
  height: 50px;
  box-shadow: 0px;
  outline: none;
}

.__UIV_SCOPE__ .card-header {
  padding: 10px;
  background: linear-gradient(90deg, #CB2D6F 20px, transparent 100%) center / 22px 22px,
		linear-gradient(#CB2D6F 20px, transparent 100%) center / 22px 22px,
		#fff;
  color: white;
  height: 100%;
  font-size: 20px;
  font-weight: 600;
  border: 1px solid white;
  border-radius: 10px;
}

.__UIV_SCOPE__ .container .card .border {
  transition: all 300ms ease-out;
  transform-origin: center center;
  position: absolute;
  top: 6px;
  left: 6px;
  width: calc(100% - 0px);
  height: calc(100% - 0px);
  border: 1px solid black;
  border-radius: 9px;
}

.__UIV_SCOPE__ .container a {
  opacity: 0;
  position: absolute;
  z-index: 1;
  width: 50%;
  height: 50%;
}

.__UIV_SCOPE__ .container a:hover,
.__UIV_SCOPE__ .container a:focus {
  transform: translateZ(50px);
}

.__UIV_SCOPE__ .container a:hover ~ .card .card-header,
.__UIV_SCOPE__ .container a:focus ~ .card .card-header {
  transform: translateZ(24px);
}

.__UIV_SCOPE__ .container a:nth-child(1) {
  top: 0;
  left: 0;
}

.__UIV_SCOPE__ .container a:nth-child(1):hover ~ .card,
.__UIV_SCOPE__ .container a:nth-child(1):focus ~ .card {
  transform: rotateX(10deg) rotateY(-10deg) translateZ(0);
  transform-origin: right bottom;
  box-shadow: 10px 20px;
}

.__UIV_SCOPE__ .container a:nth-child(2) {
  top: 0;
  right: 0;
}

.__UIV_SCOPE__ .container a:nth-child(2):hover ~ .card,
.__UIV_SCOPE__ .container a:nth-child(2):focus ~ .card {
  transform: rotateX(10deg) rotateY(10deg) translateZ(0);
  transform-origin: left bottom;
  box-shadow: -10px 20px;
}

.__UIV_SCOPE__ .container a:nth-child(3) {
  bottom: 0;
  right: 0;
}

.__UIV_SCOPE__ .container a:nth-child(3):hover ~ .card,
.__UIV_SCOPE__ .container a:nth-child(3):focus ~ .card {
  transform-origin: left top;
  transform: rotateX(-10deg) rotateY(10deg) translateZ(0);
  box-shadow: -10px -20px;
}

.__UIV_SCOPE__ .container a:nth-child(4) {
  bottom: 0;
  left: 0;
}

.__UIV_SCOPE__ .container a:nth-child(4):hover ~ .card,
.__UIV_SCOPE__ .container a:nth-child(4):focus ~ .card {
  transform-origin: right top;
  transform: rotateX(-10deg) rotateY(-10deg) translateZ(0);
  box-shadow: 10px -20px;
}
